+  return [
+    {
+      name: 'calculate',
+      description: 'Perform a basic arithmetic calculation on two numbers.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          a: { type: 'number', description: 'The first operand.' },
+          b: { type: 'number', description: 'The second operand.' },
+          operation: {
+            type: 'string',
+            enum: ['add', 'subtract', 'multiply', 'divide'],
+            description: 'The arithmetic operation to perform.',
+          },
+        },
+        required: ['a', 'b', 'operation'],
+        additionalProperties: false,
+      },
+    },
+  ];
+}
+
+export async function callTool(name, args) {
+  if (name !== 'calculate') {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+
+  const keys = Object.keys(args);
+  const missing = [...ALLOWED_FIELDS].filter((k) => !(k in args));
+  const extra = keys.filter((k) => !ALLOWED_FIELDS.has(k));
+
+  if (missing.length > 0) {
+    throw new Error(`Missing required field(s): ${missing.join(', ')}`);
+  }
+  if (extra.length > 0) {
+    throw new Error(`Unexpected field(s): ${extra.join(', ')}`);
+  }
+
+  const { a, b, operation } = args;
+
+  assertNumeric(a, 'a');
+  assertNumeric(b, 'b');
+
+  if (typeof operation !== 'string' || !Object.prototype.hasOwnProperty.call(OPERATIONS, operation)) {
+    throw new Error(`Unsupported operation: ${operation}`);
+  }
+
+  if (operation === 'divide' && b === 0) {
+    throw new Error('Division by zero is not allowed');
+  }
+
+  const result = OPERATIONS[operation](a, b);
+
+  return {
+    content: [{ type: 'text', text: String(result) }],
+  };
+}
